#[derive(Clone, PartialEq, Debug)]
pub struct BattlerAnimation {
    pub id: i32,
    pub name: DBString,
    pub speed: i32,
    pub poses: Vec<BattlerAnimationPose>,
    pub weapons: Vec<BattlerAnimationWeapon>,
}

impl Default for BattlerAnimation {
    fn default() -> Self {
        Self::default_for_engine(false)
    }
}

impl BattlerAnimation {
    pub fn default_for_engine(_is_2k3: bool) -> Self {
        Self {
            id: 0,
            name: DBString::default(),
            speed: 20,
            poses: Vec::new(),
            weapons: Vec::new(),
        }
    }

    pub fn read_lcf<R: std::io::Read + std::io::Seek>(reader: &mut crate::reader::LcfReader<R>) -> Result<Self, crate::error::LcfError> {
        let mut obj = Self::default();
        while let Some(chunk) = reader.read_chunk_header()? {
            let start_off = reader.tell()?;
            match chunk.id {
                0x01 => {
                    obj.name = reader.read_string(chunk.length)?;
                }
                0x02 => {
                    obj.speed = reader.read_int()? as i32;
                }
                0x0A => {
                    let count = reader.read_int()?;
                    obj.poses.clear();
                    for _ in 0..count {
                        let id = reader.read_int()?;
                        let mut item = BattlerAnimationPose::read_lcf(reader)?;
                        item.id = id;
                        obj.poses.push(item);
                    }
                }
                0x0B => {
                    let count = reader.read_int()?;
                    obj.weapons.clear();
                    for _ in 0..count {
                        let id = reader.read_int()?;
                        let mut item = BattlerAnimationWeapon::read_lcf(reader)?;
                        item.id = id;
                        obj.weapons.push(item);
                    }
                }
                _ => reader.skip(chunk.length)?,
            }
            let read_bytes = (reader.tell()? - start_off) as usize;
            if read_bytes < chunk.length {
                reader.skip(chunk.length - read_bytes)?;
            }
        }
        Ok(obj)
    }

    pub fn write_lcf<W: std::io::Write + std::io::Seek>(&self, writer: &mut crate::writer::LcfWriter<W>) -> Result<(), crate::error::LcfError> {
        let _def = Self::default_for_engine(writer.is_2k3());
        if writer.is_2k3() && (self.name != _def.name) {
            writer.write_dbstring_chunk(0x01, &self.name)?;
        }
        if writer.is_2k3() && (self.speed != _def.speed) {
            writer.write_int_chunk(0x02, self.speed as i32)?;
        }
        if writer.is_2k3() {
            writer.write_sub_chunk(0x0A, |w| {
            w.write_int(self.poses.len() as i32)?;
            for item in &self.poses {
                w.write_int(item.id)?;
                item.write_lcf(w)?;
            }
            Ok(())
        })?;
        }
        if writer.is_2k3() {
            writer.write_sub_chunk(0x0B, |w| {
            w.write_int(self.weapons.len() as i32)?;
            for item in &self.weapons {
                w.write_int(item.id)?;
                item.write_lcf(w)?;
            }
            Ok(())
        })?;
        }
        writer.write_int(0)?;
        Ok(())
    }
    pub fn write_xml<W: std::io::Write>(&self, writer: &mut crate::xml::XmlWriter<W>) -> Result<(), crate::error::LcfError> {
        writer.begin_element_with_id("BattlerAnimation", self.id)?;
        writer.write_node_dbstring("name", &self.name)?;
        writer.write_node_int("speed", self.speed as i32)?;
        writer.begin_element("poses")?;
        for item in &self.poses { item.write_xml(writer)?; }
        writer.end_element("poses")?;
        writer.begin_element("weapons")?;
        for item in &self.weapons { item.write_xml(writer)?; }
        writer.end_element("weapons")?;
        writer.end_element("BattlerAnimation")?;
        Ok(())
    }
}

