        self.battle_music.write_xml(writer)?;
        writer.end_element("battle_music")?;
        writer.begin_element("battle_end_music")?;
        self.battle_end_music.write_xml(writer)?;
        writer.end_element("battle_end_music")?;
        writer.begin_element("inn_music")?;
        self.inn_music.write_xml(writer)?;
