#[derive(Clone, PartialEq, Debug)]
pub struct Troop {
    pub id: i32,
    pub name: DBString,
    pub members: Vec<TroopMember>,
    pub auto_alignment: bool,
    pub terrain_set: DBBitArray,
    pub appear_randomly: bool,
    pub pages: Vec<TroopPage>,
}

impl Default for Troop {
    fn default() -> Self {
        Self::default_for_engine(false)
    }
}

impl Troop {
    pub fn default_for_engine(_is_2k3: bool) -> Self {
        Self {
            id: 0,
            name: DBString::default(),
            members: Vec::new(),
            auto_alignment: false,
            terrain_set: DBBitArray::default(),
            appear_randomly: false,
            pages: Vec::new(),
        }
    }

    pub fn read_lcf<R: std::io::Read + std::io::Seek>(reader: &mut crate::reader::LcfReader<R>) -> Result<Self, crate::error::LcfError> {
        let mut obj = Self::default();
        while let Some(chunk) = reader.read_chunk_header()? {
            let start_off = reader.tell()?;
            match chunk.id {
                0x01 => {
                    obj.name = reader.read_string(chunk.length)?;
                }
                0x02 => {
                    let count = reader.read_int()?;
                    obj.members.clear();
                    for _ in 0..count {
                        let id = reader.read_int()?;
                        let mut item = TroopMember::read_lcf(reader)?;
                        item.id = id;
                        obj.members.push(item);
                    }
                }
                0x03 => {
                    obj.auto_alignment = reader.read_bool()?;
                }
                0x04 => { let _ = reader.read_int()?; }
                0x05 => {
                    obj.terrain_set = reader.read_bit_array(chunk.length)?;
                }
                0x06 => {
                    obj.appear_randomly = reader.read_bool()?;
                }
                0x0B => {
                    let count = reader.read_int()?;
                    obj.pages.clear();
                    for _ in 0..count {
                        let id = reader.read_int()?;
                        let mut item = TroopPage::read_lcf(reader)?;
                        item.id = id;
                        obj.pages.push(item);
                    }
                }
                _ => reader.skip(chunk.length)?,
            }
            let read_bytes = (reader.tell()? - start_off) as usize;
            if read_bytes < chunk.length {
                reader.skip(chunk.length - read_bytes)?;
            }
        }
        Ok(obj)
    }

    pub fn write_lcf<W: std::io::Write + std::io::Seek>(&self, writer: &mut crate::writer::LcfWriter<W>) -> Result<(), crate::error::LcfError> {
        let _def = Self::default_for_engine(writer.is_2k3());
        if self.name != _def.name {
            writer.write_dbstring_chunk(0x01, &self.name)?;
        }
        writer.write_sub_chunk(0x02, |w| {
            w.write_int(self.members.len() as i32)?;
            for item in &self.members {
                w.write_int(item.id)?;
                item.write_lcf(w)?;
            }
            Ok(())
        })?;
        if writer.is_2k3() && (self.auto_alignment != _def.auto_alignment) {
            writer.write_bool_chunk(0x03, self.auto_alignment)?;
        }
        if writer.is_2k3() && (self.appear_randomly != _def.appear_randomly) {
            writer.write_bool_chunk(0x06, self.appear_randomly)?;
        }
        writer.write_sub_chunk(0x0B, |w| {
            w.write_int(self.pages.len() as i32)?;
            for item in &self.pages {
                w.write_int(item.id)?;
                item.write_lcf(w)?;
            }
            Ok(())
        })?;
        writer.write_int(0)?;
        Ok(())
    }
    pub fn write_xml<W: std::io::Write>(&self, writer: &mut crate::xml::XmlWriter<W>) -> Result<(), crate::error::LcfError> {
        writer.begin_element_with_id("Troop", self.id)?;
        writer.write_node_dbstring("name", &self.name)?;
        writer.begin_element("members")?;
        for item in &self.members { item.write_xml(writer)?; }
        writer.end_element("members")?;
        writer.write_node_bool("auto_alignment", self.auto_alignment)?;
        writer.write_node_bool("appear_randomly", self.appear_randomly)?;
        writer.begin_element("pages")?;
        for item in &self.pages { item.write_xml(writer)?; }
        writer.end_element("pages")?;
        writer.end_element("Troop")?;
        Ok(())
    }
}

