#[derive(Clone, PartialEq, Debug)]
pub struct TroopPage {
    pub id: i32,
    pub condition: TroopPageCondition,
    pub event_commands: Vec<EventCommand>,
}

impl Default for TroopPage {
    fn default() -> Self {
        Self::default_for_engine(false)
    }
}

impl TroopPage {
    pub fn default_for_engine(_is_2k3: bool) -> Self {
        Self {
            id: 0,
            condition: TroopPageCondition::default(),
            event_commands: Vec::new(),
        }
    }

    pub fn read_lcf<R: std::io::Read + std::io::Seek>(reader: &mut crate::reader::LcfReader<R>) -> Result<Self, crate::error::LcfError> {
        let mut obj = Self::default();
        while let Some(chunk) = reader.read_chunk_header()? {
            let start_off = reader.tell()?;
            match chunk.id {
                0x02 => {
                    obj.condition = TroopPageCondition::read_lcf(reader)?;
                }
                0x0B => { let _ = reader.read_int()?; }
                0x0C => {
                    let end_pos = start_off + chunk.length as u64;
                    obj.event_commands.clear();
                    loop {
                        if reader.tell()? >= end_pos { break; }
                        let cmd = crate::types::EventCommand::read_lcf(reader)?;
                        if cmd.code == 0 {
                            for _ in 0..3 { if reader.tell()? < end_pos { let _ = reader.read_u8()?; } }
                            break;
                        }
                        obj.event_commands.push(cmd);
                    }
                }
                _ => reader.skip(chunk.length)?,
            }
            let read_bytes = (reader.tell()? - start_off) as usize;
            if read_bytes < chunk.length {
                reader.skip(chunk.length - read_bytes)?;
            }
        }
        Ok(obj)
    }

    pub fn write_lcf<W: std::io::Write + std::io::Seek>(&self, writer: &mut crate::writer::LcfWriter<W>) -> Result<(), crate::error::LcfError> {
        let _def = Self::default_for_engine(writer.is_2k3());
        writer.write_sub_chunk(0x02, |w| self.condition.write_lcf(w))?;
        writer.write_sub_chunk(0x0C, |w| {
            for cmd in &self.event_commands { cmd.write_lcf(w)?; }
            for _ in 0..4 { w.write_int(0)?; }
            Ok(())
        })?;
        writer.write_int(0)?;
        Ok(())
    }
    pub fn write_xml<W: std::io::Write>(&self, writer: &mut crate::xml::XmlWriter<W>) -> Result<(), crate::error::LcfError> {
        writer.begin_element_with_id("TroopPage", self.id)?;
        writer.begin_element("condition")?;
        self.condition.write_xml(writer)?;
        writer.end_element("condition")?;
        writer.begin_element("event_commands")?;
        for item in &self.event_commands { item.write_xml(writer)?; }
        writer.end_element("event_commands")?;
        writer.end_element("TroopPage")?;
        Ok(())
    }
}

